def _get_release_or_404(release_id: int, db: Session) -> Release:
    """Load release or raise 404."""
    release = db.query(Release).options(joinedload(Release.project), joinedload(Release.manager)).filter(
        Release.release_id == release_id
    ).first()
    if not release:
        raise HTTPException(status_code=404, detail="Release not found")
    return release


