# Generated by GitHub Copilot
def _compute_readiness(prs: List[PullRequest], work_items: List[WorkItem], findings: List[SecurityFinding], analysis: AIAnalysis | None) -> ReadinessBreakdown:
    """Compute readiness 0-100 with four weighted categories."""
    pr_total = len(prs)
    pr_done = sum(1 for p in prs if p.status in ("Merged", "Closed"))
    pr_open = pr_total - pr_done
    if pr_total == 0:
        pr_score = 0
        pr_detail = "No PRs attached"
    else:
        pr_score = round((pr_done / pr_total) * 25)
        pr_detail = f"{pr_done} of {pr_total} merged / closed"
        if pr_open:
            pr_detail += f" ({pr_open} still open)"

    wi_total = len(work_items)
    wi_done = sum(1 for w in work_items if w.status == "Done")
    wi_open_hi = sum(1 for w in work_items if w.status != "Done" and (w.priority or "").lower() == "high")
    wi_open_lo = sum(1 for w in work_items if w.status != "Done" and (w.priority or "").lower() != "high")
    if wi_total == 0:
        def_score = 25
        def_detail = "No work items - clean slate"
    else:
        weighted_open = wi_open_hi * 2 + wi_open_lo
        weighted_total = wi_total + wi_open_hi
        def_score = max(0, round(25 - (weighted_open / weighted_total) * 25))
        def_detail = f"{wi_done} of {wi_total} done"
        if wi_open_hi:
            def_detail += f" ({wi_open_hi} High priority open)"

    f_total = len(findings)
    f_resolved = sum(1 for f in findings if f.status == "Resolved")
    f_open = f_total - f_resolved
    f_hi_open = sum(1 for f in findings if f.status != "Resolved" and (f.severity or "").lower() == "high")
    if f_total == 0:
        risk_score = 25
        risk_detail = "No security findings logged"
    else:
        risk_score = round((f_resolved / f_total) * 25)
        risk_detail = f"{f_resolved} of {f_total} resolved"
        if f_open:
            risk_detail += f" ({f_open} still open)"
            if f_hi_open:
                risk_detail += f", {f_hi_open} High severity"

    doc_st = (analysis.status or "NOT_GENERATED") if analysis else "NOT_GENERATED"
    if doc_st == "NOT_GENERATED" or analysis is None:
        doc_score = 0
        doc_detail = "Not generated yet"
    elif doc_st == "GENERATED":
        doc_score = 15
        doc_detail = "Generated - pending approval"
    else:
        doc_score = 25
        doc_detail = "Approved"

    total = pr_score + def_score + risk_score + doc_score

    open_wi = sum(1 for w in work_items if w.status != "Done")
    open_risks = sum(1 for f in findings if f.status != "Resolved")
    if open_wi > 0 or open_risks > 0:
        risk_level = "HIGH"
    elif total >= 80:
        risk_level = "LOW"
    else:
        risk_level = "MEDIUM"

    return ReadinessBreakdown(
        total=total,
        risk_level=risk_level,
        categories=[
            ReadinessCategoryScore(label="Pull Requests", score=pr_score, max_score=25, detail=pr_detail),
            ReadinessCategoryScore(label="Work Items", score=def_score, max_score=25, detail=def_detail),
            ReadinessCategoryScore(label="Security Risks", score=risk_score, max_score=25, detail=risk_detail),
            ReadinessCategoryScore(label="Documentation", score=doc_score, max_score=25, detail=doc_detail),
        ],
    )


# Generated by GitHub Copilot
def _compute_decision(work_items: List[WorkItem], findings: List[SecurityFinding], analysis: AIAnalysis | None, go_no_go_override: str | None = None) -> ReleaseDecision:
    """Compute release decision summary."""
    open_wi = sum(1 for w in work_items if w.status != "Done")
    open_risks = sum(1 for f in findings if f.status != "Resolved")
    doc_st = (analysis.status or "NOT_GENERATED") if analysis else "Not Generated"
    docs_status = doc_st.replace("_", " ").title()

    if go_no_go_override:
        go_no_go = go_no_go_override
    elif open_wi > 0 or open_risks > 0:
        go_no_go = "Blocked"
    elif analysis is None or doc_st == "NOT_GENERATED":
        go_no_go = "In Review"
    elif doc_st == "APPROVED":
        go_no_go = "Approved"
    else:
        go_no_go = "In Review"

    return ReleaseDecision(
        open_defects=open_wi,
        open_security_risks=open_risks,
        docs_status=docs_status,
        go_no_go=go_no_go,
    )


# Generated by GitHub Copilot
@router.get("/releases/{release_id}/overview", response_model=ReleaseOverview)
def get_release_overview(release_id: int, db: Session = Depends(get_db)):
    """Return release overview with readiness and decision."""
    release = _get_release_or_404(release_id, db)
    prs = db.query(PullRequest).filter(PullRequest.release_id == release_id).all()
    items = db.query(WorkItem).filter(WorkItem.release_id == release_id).all()
    findings = db.query(SecurityFinding).filter(SecurityFinding.release_id == release_id).all()
    analysis = db.query(AIAnalysis).filter(AIAnalysis.release_id == release_id).first()

    readiness = _compute_readiness(prs, items, findings, analysis)

    return ReleaseOverview(
        release=_release_to_response(release, readiness_pct=readiness.total),
        pull_requests=[PullRequestResponse.model_validate(p) for p in prs],
        defects=[_work_item_to_response(w) for w in items],
        security_risks=[_finding_to_response(f) for f in findings],
        doc=_analysis_to_response(analysis) if analysis else None,
        decision=_compute_decision(items, findings, analysis, release.go_no_go_override),
        readiness=readiness,
    )


