@router.patch("/releases/{release_id}/go-no-go")
def update_go_no_go(release_id: int, payload: GoNoGoUpdate, db: Session = Depends(get_db)):
    """Set the manual Go/No-Go override for a release."""
    valid = {"GO", "GO (Tentative)", "NO-GO", ""}
    value = payload.go_no_go
    if value not in valid:
        raise HTTPException(status_code=400, detail=f"Invalid value. Must be one of: {', '.join(v for v in valid if v)}")
    release = _get_release_or_404(release_id, db)
    release.go_no_go_override = value if value else None
    db.commit()
    return {"status": "ok", "go_no_go": value}


