@router.post("/releases/{release_id}/docs/generate", response_model=AIAnalysisResponse, status_code=status.HTTP_201_CREATED)
def generate_docs(release_id: int, db: Session = Depends(get_db)):
    """Generate docs through Bedrock client and persist analysis."""
    release = _get_release_or_404(release_id, db)
    prs = db.query(PullRequest).filter(PullRequest.release_id == release_id).all()
    items = db.query(WorkItem).filter(WorkItem.release_id == release_id).all()
    findings = db.query(SecurityFinding).filter(SecurityFinding.release_id == release_id).all()

    owner = None
    if release.manager:
        owner = release.manager.name
    elif release.project and release.project.manager:
        owner = release.project.manager.name

    context = {
        "release_name": release.release_name,
        "version": release.version,
        "owner": owner,
        "target_date": str(release.release_date) if release.release_date else None,
        "project_name": release.project.project_name if release.project else None,
        "project_description": None,
        "release_summary": release.release_summary,
        "pull_requests": [
            {"pr_number": str(p.pr_number), "title": p.title or "", "status": p.status or ""}
            for p in prs
        ],
        "defects": [
            {"jira_key": w.issue_key, "title": w.title or "", "severity": w.priority or "Medium", "status": w.status or "Open"}
            for w in items
        ],
        "security_risks": [
            {"sec_id": f.tool_name or str(f.finding_id), "description": f.title or "", "status": f.status or "Open"}
            for f in findings
        ],
    }

    try:
        notes, impact_text = generate_release_summary(context)
    except RuntimeError as exc:
        raise HTTPException(status_code=status.HTTP_503_SERVICE_UNAVAILABLE, detail=f"Bedrock generation failed: {exc}")

    analysis = db.query(AIAnalysis).filter(AIAnalysis.release_id == release_id).first()
    if analysis:
        analysis.release_notes = notes
        analysis.risk_summary = impact_text
        analysis.status = "GENERATED"
        analysis.generated_time = datetime.now(timezone.utc)
    else:
        analysis = AIAnalysis(
            release_id=release_id,
            release_notes=notes,
            risk_summary=impact_text,
            status="GENERATED",
            generated_time=datetime.now(timezone.utc),
        )
        db.add(analysis)

    db.commit()
    db.refresh(analysis)
    return _analysis_to_response(analysis)


# ── Branch-based documentation generation (added from v3) ──────────────────

def _parse_github_branch_url(url: str) -> tuple[str, str, str]:
    """
    Parse owner, repo, and branch name from a GitHub branch URL.

    Supports:
      https://github.com/{owner}/{repo}/commits/{branch}/
      https://github.com/{owner}/{repo}/tree/{branch}
      https://github.com/{owner}/{repo}/compare/{branch}
    """
    parsed = urlparse(url.rstrip("/"))
    parts  = [p for p in parsed.path.strip("/").split("/") if p]
    # parts: [owner, repo, segment, branch, ...]
    if len(parts) >= 4 and parts[2] in ("commits", "tree", "compare"):
        return parts[0], parts[1], parts[3]
    if len(parts) >= 3 and parts[2] in ("commits", "tree", "compare"):
        raise ValueError(f"Branch name missing in GitHub URL: {url}")
    raise ValueError(
        f"Unrecognised GitHub branch URL format: '{url}'. "
        "Expected https://github.com/{{owner}}/{{repo}}/commits/{{branch}}/"
    )


@router.post(
    "/releases/{release_id}/docs/generate-from-branch",
    response_model=AIAnalysisResponse,
    status_code=status.HTTP_201_CREATED,
)
def generate_docs_from_branch(release_id: int, db: Session = Depends(get_db)):
    """
    Generate technical documentation directly from the release's linked GitHub branch.
    release.release_branch must be a GitHub URL such as:
      https://github.com/owner/repo/tree/branch-name
    Owner, repo, and branch are parsed from the URL automatically.
    GITHUB_TOKEN env var is used for authentication.
    """
    release = _get_release_or_404(release_id, db)

    branch_url = release.release_branch
    if not branch_url:
        raise HTTPException(
            status_code=status.HTTP_422_UNPROCESSABLE_ENTITY,
            detail="Release has no release_branch set. Save a GitHub branch URL in the release first.",
        )

    try:
        gh_owner, gh_repo, branch = _parse_github_branch_url(branch_url)
    except ValueError as exc:
        raise HTTPException(
            status_code=status.HTTP_422_UNPROCESSABLE_ENTITY,
            detail=str(exc),
        )

    gh_token = os.environ.get("GITHUB_TOKEN")

    # ── Fetch branch data ──────────────────────────────────────────────────
    raw_commits = get_branch_commits(gh_owner, gh_repo, branch, token=gh_token)
    commits = [
        {
            "sha": c.get("sha", ""),
            "message": c.get("commit", {}).get("message", ""),
            "author": c.get("commit", {}).get("author", {}).get("name", "unknown"),
            "date": c.get("commit", {}).get("author", {}).get("date", ""),
        }
        for c in raw_commits
    ]

    file_tree  = get_branch_file_tree(gh_owner, gh_repo, branch, token=gh_token)
    file_paths = [f["path"] for f in file_tree]

    # Fetch source files (Python / JS / TS / Java / Go / C# / Ruby), cap at 10
    source_extensions = (".py", ".js", ".ts", ".java", ".go", ".cs", ".rb")
    source_files = [p for p in file_paths if p.endswith(source_extensions)]
    file_contents: dict[str, str] = {}
    for path in source_files[:10]:
        content = get_file_content(gh_owner, gh_repo, path, ref=branch, token=gh_token)
        if content:
            file_contents[path] = content

    # ── Build context ──────────────────────────────────────────────────────
    owner_name = None
    if release.manager:
        owner_name = release.manager.name
    elif release.project and release.project.manager:
        owner_name = release.project.manager.name

    context = {
        "repo_url": f"https://github.com/{gh_owner}/{gh_repo}",
        "branch": branch,
        "release_name": release.release_name,
        "version": release.version,
        "owner": owner_name,
        "commits": commits,
        "files": file_paths,
        "file_contents": file_contents,
    }

    try:
        notes, impact_text = generate_branch_documentation(context)
    except RuntimeError as exc:
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail=f"Branch documentation generation failed: {exc}",
        )

    analysis = db.query(AIAnalysis).filter(AIAnalysis.release_id == release_id).first()
    if analysis:
        analysis.release_notes  = notes
        analysis.risk_summary   = impact_text
        analysis.status         = "GENERATED"
        analysis.generated_time = datetime.now(timezone.utc)
    else:
        analysis = AIAnalysis(
            release_id=release_id,
            release_notes=notes,
            risk_summary=impact_text,
            status="GENERATED",
            generated_time=datetime.now(timezone.utc),
        )
        db.add(analysis)

    db.commit()
    db.refresh(analysis)
    return _analysis_to_response(analysis)


