@router.put("/releases/{release_id}/docs", response_model=AIAnalysisResponse)
def update_docs(release_id: int, doc_data: AIAnalysisUpdate, db: Session = Depends(get_db)):
    """Update release docs fields."""
    analysis = db.query(AIAnalysis).filter(AIAnalysis.release_id == release_id).first()
    if not analysis:
        raise HTTPException(status_code=404, detail="No documentation found for this release")
    for field, value in doc_data.model_dump(exclude_unset=True).items():
        setattr(analysis, field, value)
    db.commit()
    db.refresh(analysis)
    return _analysis_to_response(analysis)


# Generated by GitHub Copilot
@router.post("/releases/{release_id}/docs/approve", response_model=AIAnalysisResponse)
def approve_docs(release_id: int, db: Session = Depends(get_db)):
    """Approve generated docs for release."""
    analysis = db.query(AIAnalysis).filter(AIAnalysis.release_id == release_id).first()
    if not analysis or analysis.status == "NOT_GENERATED":
        raise HTTPException(status_code=400, detail="Docs must be generated before approving")
    analysis.status = "APPROVED"
    db.commit()
    db.refresh(analysis)
    return _analysis_to_response(analysis)


