# Generated by GitHub Copilot
@router.post("/readiness-score", response_model=ReadinessScoreResponse)
def compute_readiness_score(payload: ReadinessScoreRequest):
    """Standalone readiness score calculator without DB access."""
    from datetime import date as date_type

    prs = payload.pull_requests
    defects = payload.defects
    risks = payload.security_risks

    pr_total = len(prs)
    if pr_total == 0:
        pr_score, pr_detail = 0, "No pull requests provided"
    else:
        pr_done = sum(1 for p in prs if p.status in ("Merged", "Closed"))
        pr_score = round((pr_done / pr_total) * 25)
        pr_detail = f"{pr_done} of {pr_total} merged/closed"

    wi_total = len(defects)
    if wi_total == 0:
        def_score, def_detail = 25, "No defects - clean slate"
    else:
        wi_done = sum(1 for d in defects if d.status == "Done")
        wi_hi_open = sum(1 for d in defects if d.status != "Done" and (d.priority or "").lower() == "high")
        wi_lo_open = sum(1 for d in defects if d.status != "Done" and (d.priority or "").lower() != "high")
        weighted_open = wi_hi_open * 2 + wi_lo_open
        weighted_total = wi_total + wi_hi_open
        def_score = max(0, round(25 - (weighted_open / weighted_total) * 25))
        def_detail = f"{wi_done} of {wi_total} done"
        if wi_hi_open:
            def_detail += f" ({wi_hi_open} High priority open)"

    r_total = len(risks)
    if r_total == 0:
        risk_score, risk_detail = 25, "No security risks provided"
    else:
        r_resolved = sum(1 for r in risks if r.status == "Resolved")
        r_open = r_total - r_resolved
        risk_score = round((r_resolved / r_total) * 25)
        risk_detail = f"{r_resolved} of {r_total} resolved"
        if r_open:
            risk_detail += f" ({r_open} still open)"

    doc_score, doc_detail = 0, "Not provided (standalone mode)"

    total = pr_score + def_score + risk_score + doc_score

    open_wi_cnt = sum(1 for d in defects if d.status != "Done")
    open_r_cnt = sum(1 for r in risks if r.status != "Resolved")
    if open_wi_cnt > 0 or open_r_cnt > 0:
        risk_level = "HIGH"
    elif total >= 80:
        risk_level = "LOW"
    else:
        risk_level = "MEDIUM"

    readiness = ReadinessBreakdown(
        total=total,
        categories=[
            ReadinessCategoryScore(label="Pull Requests", score=pr_score, max_score=25, detail=pr_detail),
            ReadinessCategoryScore(label="Work Items", score=def_score, max_score=25, detail=def_detail),
            ReadinessCategoryScore(label="Security Risks", score=risk_score, max_score=25, detail=risk_detail),
            ReadinessCategoryScore(label="Documentation", score=doc_score, max_score=25, detail=doc_detail),
        ],
        risk_level=risk_level,
    )

    days_to_target = None
    if payload.target_date:
        days_to_target = (payload.target_date - date_type.today()).days

    return ReadinessScoreResponse(
        readiness=readiness,
        target_date=payload.target_date,
        days_to_target=days_to_target,
    )
